1	import { hashToken, verify as verifyToken, type Caller } from "./auth.js";
2	import { askFor, fits, framesForGesture, loadoutFor, profileOf, setupFor } from "./control.js";
3	import { askAllowed } from "./asking.js";
4	import { apiGatewayPoster, type Poster } from "./live.js";
5	import { dynamoLive, type LiveStore } from "./live.js";
6	import { dynamoStore, type Ask, type Store } from "./store.js";
7	import { dynamoRaces, type RaceStore } from "./races.js";
8	import { annotate } from "./xray.js";
9	import { randomBytes } from "node:crypto";
10	
11	/**
12	 * The socket's three moments.
13	 *
14	 * Connect: the token rides in the query string, because a browser's
15	 * WebSocket cannot set a header. It is checked the same way the HTTP API
16	 * checks a bearer, and a bad one is refused before the socket opens.
17	 * Message: the one thing a device says is which session it is watching;
18	 * it must be a member, and a session it may not see is ignored without
19	 * saying whether it exists. Disconnect: the rows go.
20	 *
21	 * A run shared by link admits a socket with no account: `?t=<token>&run=<id>`
22	 * opens a connection that watches that run and nothing else, and says
23	 * nothing it is told.
24	 *
25	 * Nothing else. Moves still travel over HTTP; the socket is a doorbell.
26	 */
27	
28	export interface WsEvent {
29	  requestContext: { routeKey: string; connectionId: string };
30	  queryStringParameters?: Record<string, string | undefined>;
31	  body?: string;
32	  isBase64Encoded?: boolean;
33	}
34	
35	export interface WsDeps {
36	  live: LiveStore;
37	  /** A way to post to connections; absent in a test that only checks routing. */
38	  poster?: Poster;
39	  store: Pick<Store, "getSession" | "streamKeyOwner" | "manifest" | "getSnapshot" | "addAsk" | "updateSession">;
40	  races: Pick<RaceStore, "getRace">;
41	  verify: (authorization: string | undefined) => Promise<Caller>;
42	  now?: () => string;
43	}
44	
45	interface WsResult {
46	  statusCode: number;
47	  body?: string;
48	}
49	
50	/**
51	 * A socket opened by something that drives a game rather than draws a
52	 * scoreboard.
53	 *
54	 * It arrives on the same addresses as every other watcher, with the same
55	 * keys, because what it is allowed to see is exactly what a watcher is
56	 * allowed to see. What it asks for in addition is to be told in
57	 * operations, and to say which player it is sitting in front of.
58	 */
59	function attachedOf(event: WsEvent, run: string): { control: true; seat?: string; run: string } | undefined {
60	  if (event.queryStringParameters?.["as"] !== "control") return undefined;
61	  const raw = (event.queryStringParameters?.["seat"] ?? "").trim().slice(0, 40);
62	  return { control: true, ...(raw ? { seat: raw } : {}), run };
63	}
64	
65	/**
66	 * A socket that presses rather than draws.
67	 *
68	 * It signs in as the account, the way the app's own devices do, because
69	 * what it may do is what the owner may do. It names no run at connect: it
70	 * is told which runs are being held, and picks. A link's token and a
71	 * stream key are refused here, which is why this is read only on the
72	 * signed-in branch below.
73	 */
74	function deckOf(event: WsEvent): { deck: true } | undefined {
75	  return event.queryStringParameters?.["as"] === "deck" ? { deck: true } : undefined;
76	}
77	
78	/**
79	 * Whether this watcher is a device that could take a press.
80	 *
81	 * A link's socket and a scene's are not; an attached tool is told in
82	 * operations and writes nothing; a deck is the thing asking. What is
83	 * left is a signed-in device with the run open, which is the page.
84	 */
85	function writes(w: { sub: string; control?: boolean; deck?: boolean }): boolean {
86	  return !w.control && !w.deck && !w.sub.startsWith("public:") && !w.sub.startsWith("stream:");
87	}
88	
89	export async function route(event: WsEvent, deps: WsDeps): Promise<WsResult> {
90	  const { routeKey, connectionId } = event.requestContext;
91	  const now = deps.now ?? (() => new Date().toISOString());
92	  // The socket has no method, only which of its three moments this is.
93	  annotate({ method: "WS", route: routeKey });
94	
95	  /**
96	   * The account's runs that something is holding open.
97	   *
98	   * Not the run that moved most recently, which is all a watch key can
99	   * know: a deck presses, and a press wants a device on the other end.
100	   * The newest twenty are considered, because an account's manifest is
101	   * every run it has ever played and a deck's picker is a short list.
102	   */
103	  const heldRuns = async (sub: string) => {
104	    const { sessions } = await deps.store.manifest(sub);
105	    const mine = sessions
106	      .filter((p) => p.role === "owner" && !p.deletedAt && !p.endedAt)
107	      .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0))
108	      .slice(0, 20);
109	    const held = await Promise.all(mine.map(async (p) => ((await deps.live.watchers(p.id)).some(writes) ? p : null)));
110	    return held
111	      .filter((p): p is (typeof mine)[number] => p !== null)
112	      .map((p) => ({
113	        id: p.id,
114	        ...(p.name ? { name: p.name } : {}),
115	        ...(p.packTitle ? { packTitle: p.packTitle } : {}),
116	        held: true as const,
117	      }));
118	  };
119	
120	  /**
121	   * Said to an account's decks whenever the held set changes, and once on
122	   * connect, which is the same message: a deck comes up before anything is
123	   * running, so a list fetched once would stay empty all evening.
124	   */
125	  const tellDecks = async (sub: string, only?: string): Promise<void> => {
126	    const poster = deps.poster;
127	    if (!poster) return;
128	    // Everything in here, one guard: a deck that cannot be given its list
129	    // right now is still connected and hears the next push. A rejection
130	    // out of `manifest` or `watchers` must not turn a $connect into a 500,
131	    // which would refuse the deck outright.
132	    try {
133	      const decks = only ? [{ connectionId: only }] : await deps.live.decksOf(sub);
134	      if (decks.length === 0) return;
135	      const line = JSON.stringify({ t: "runs", runs: await heldRuns(sub) });
136	      for (const d of decks) {
137	        if ((await poster.post(d.connectionId, line)) === "gone") await deps.live.disconnect(d.connectionId);
138	      }
139	    } catch (error) {
140	      console.error("live: could not say which runs are held", error);
141	    }
142	  };
143	
144	  if (routeKey === "$connect") {
145	    const t = event.queryStringParameters?.["t"];
146	    const run = event.queryStringParameters?.["run"];
147	    if (t && run) {
148	      const session = await deps.store.getSession(run);
149	      if (!session || session.meta.deletedAt || !session.meta.publicTokenHash || hashToken(t) !== session.meta.publicTokenHash)
150	        return { statusCode: 401, body: "not shared" };
151	      const who = `public:${run}`;
152	      const attached = attachedOf(event, run);
153	      await deps.live.connect(connectionId, who, now(), attached);
154	      await deps.live.watch(connectionId, run, who, now(), attached);
155	      return { statusCode: 200 };
156	    }
157	    /**
158	     * A scene's socket, opened on the account's watch key.
159	     *
160	     * The address in a browser source or a bot's client is set up once and
161	     * lives for months, so it cannot name a run: it names the account, and
162	     * this finds the run. Of the runs open to watchers, the one moved most
163	     * recently, which is the one being played.
164	     *
165	     * Which run it watches is settled when it connects. A socket open
166	     * across the start of a new run goes on watching the old one until it
167	     * is opened again; the bot hears `run-ended` on the old one, which is
168	     * the moment to reconnect.
169	     */
170	    const k = event.queryStringParameters?.["k"];
171	    if (k) {
172	      const owner = await deps.store.streamKeyOwner(hashToken(k));
173	      // A press key belongs in a bot's settings, never in a scene.
174	      if (!owner || owner.kind !== "watch") return { statusCode: 401, body: "not a key for watching" };
175	      const named = (event.queryStringParameters?.["run"] ?? "").trim();
176	      const { sessions } = await deps.store.manifest(owner.sub);
177	      const live = sessions
178	        .filter((p) => p.role === "owner" && !p.deletedAt && !p.endedAt && (!named || p.id === named))
179	        .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0));
180	      let watching: string | null = null;
181	      for (const p of live)
182	        if ((await deps.store.getSession(p.id))?.meta.publicTokenHash) {
183	          watching = p.id;
184	          break;
185	        }
186	      if (!watching) return { statusCode: 401, body: "no run is open to watch" };
187	      const who = `stream:${owner.sub}`;
188	      const attached = attachedOf(event, watching);
189	      await deps.live.connect(connectionId, who, now(), attached);
190	      await deps.live.watch(connectionId, watching, who, now(), attached);
191	      return { statusCode: 200 };
192	    }
193	    const token = event.queryStringParameters?.["token"];
194	    let caller: Caller;
195	    try {
196	      caller = await deps.verify(token ? `Bearer ${token}` : undefined);
197	    } catch {
198	      return { statusCode: 401, body: "sign in first" };
199	    }
200	    const deck = deckOf(event);
201	    await deps.live.connect(connectionId, caller.sub, now(), deck);
202	    if (deck) await tellDecks(caller.sub, connectionId);
203	    return { statusCode: 200 };
204	  }
205	
206	  /**
207	   * Who has a tool on the game right now, said to everyone watching.
208	   *
209	   * The whole set every time rather than a joining and a leaving. A table
210	   * that missed one message would otherwise show a tool that went home an
211	   * hour ago, or miss one that is about to be sent a curse, and there is
212	   * no cheap way to notice you missed it. A list is idempotent; a delta is
213	   * a thing to keep in step.
214	   */
215	  const tellWhoIsAttached = async (run: string): Promise<void> => {
216	    const poster = deps.poster;
217	    if (!poster) return;
218	    const watching = await deps.live.watchers(run);
219	    const tools = watching.filter((w) => w.control).map((w) => ({ ...(w.seat ? { seat: w.seat } : {}), ...(w.app ? { app: w.app } : {}) }));
220	    const decks = watching.filter((w) => w.deck).length;
221	    const line = JSON.stringify({ t: "gesture", id: run, kind: "tools", data: { tools, count: tools.length, decks }, at: now() });
222	    for (const w of watching) {
223	      // A tool is told in operations, never in words about itself.
224	      if (w.control) continue;
225	      try {
226	        if ((await poster.post(w.connectionId, line)) === "gone") await deps.live.disconnect(w.connectionId);
227	      } catch (error) {
228	        console.error("live: could not say who is attached", error);
229	      }
230	    }
231	  };
232	
233	  if (routeKey === "$disconnect") {
234	    // Read before it goes: a tool leaving is news, and afterwards there is
235	    // nothing left to say which run it was on.
236	    const leaving = await deps.live.connection(connectionId);
237	    await deps.live.disconnect(connectionId);
238	    if (leaving?.control && leaving.run) await tellWhoIsAttached(leaving.run);
239	    // A deck leaving its run is news the same way a tool leaving is: the
240	    // page is told, as it was told the deck came on.
241	    if (leaving?.deck && leaving.run) await tellWhoIsAttached(leaving.run);
242	    // A page closing may have been the last thing holding a run, and a deck
243	    // whose keys still look live is worse than one that says so.
244	    if (leaving && !leaving.deck && writes(leaving)) await tellDecks(leaving.sub);
245	    return { statusCode: 200 };
246	  }
247	
248	  // $default: a message.
249	  const conn = await deps.live.connection(connectionId);
250	  if (!conn) return { statusCode: 401, body: "unknown connection" };
251	  let message: unknown;
252	  try {
253	    const raw = event.isBase64Encoded ? Buffer.from(event.body ?? "", "base64").toString("utf8") : (event.body ?? "");
254	    message = JSON.parse(raw);
255	  } catch {
256	    return { statusCode: 400, body: "JSON, please" };
257	  }
258	  if (!message || typeof message !== "object") return { statusCode: 400, body: "an object" };
259	  const m = message as Record<string, unknown>;
260	
261	  /**
262	   * A tool saying what it is and what it can do.
263	   *
264	   * The one message an attached tool sends, and the only one any of them
265	   * may: what comes back is the run's own terms, the settings it wants in
266	   * force before anything is rolled. Everything else it hears is sent
267	   * because the table moved, never because it asked.
268	   *
269	   * What the tool can do is not read here. A source that only ever sends
270	   * what a profile names cannot send an operation an old build lacks, and
271	   * a build that receives one refuses it by name, which is the answer in
272	   * both directions.
273	   */
274	  if (conn.control && m["t"] === "hello" && conn.run) {
275	    // What it calls itself is remembered, because a profile written for
276	    // one program must not drive another that happens to share an
277	    // operation name.
278	    const app = typeof m["app"] === "string" ? m["app"].trim().slice(0, 64) : "";
279	    await deps.live.watch(connectionId, conn.run, conn.sub, now(), {
280	      control: true,
281	      ...(conn.seat ? { seat: conn.seat } : {}),
282	      ...(app ? { app } : {}),
283	      run: conn.run,
284	    });
285	
286	    // The table hears that somebody's game is on the other end of this.
287	    // Said here rather than at connect, because until the hello arrives
288	    // there is no seat and no name to say, and a row with neither is not
289	    // worth drawing.
290	    await tellWhoIsAttached(conn.run);
291	
292	    const poster = deps.poster;
293	    if (!poster) return { statusCode: 200 };
294	    const snapshot = await deps.store.getSnapshot(conn.run);
295	    const profile = snapshot ? profileOf(snapshot.snapshot) : null;
296	    // Told rather than left silent: a tool sitting there doing nothing
297	    // is the most confusing thing this could do. Which is what it did
298	    // until now in the one case that matters most, the run it found
299	    // having no rules at all: an address names an account and the
300	    // server picks the run, so a tool can attach perfectly to a run
301	    // nobody is playing and report itself connected for ever.
302	    const session = await deps.store.getSession(conn.run);
303	    const which = session?.meta.packTitle ?? "a run";
304	    /**
305	     * Who has already had the parts of the terms that are given once.
306	     *
307	     * A seat, or the table where a tool named none. The terms go out on
308	     * every attach, because a tool that restarted is holding none of
309	     * them and a setting applied twice is the same setting. A gift is
310	     * not: a run whose terms hand over runes or an item handed them over
311	     * again on every reconnect, and by the third one it is a different
312	     * game. So the run remembers, and those parts are left out.
313	     */
314	    const whose = conn.seat || "the table";
315	    const given = session?.meta.termsGiven ?? [];
316	    const gotLoadout = session?.meta.loadoutGiven ?? [];
317	    /*
318	     * Two effects, not one. The pack's terms and the loadout chosen for
319	     * this run are one list in the profile and go out as two applies,
320	     * because the loadout has a button that re-sends it and a tool
321	     * re-applying an id takes the old one off first.
322	     */
323	    let terms: { frame: string; gave: boolean } | null = null;
324	    let loadout: { frame: string; gave: boolean } | null = null;
325	    const lines: string[] = [];
326	    if (!profile) {
327	      lines.push(
328	        JSON.stringify({
329	          t: "note",
330	          text: `Attached to ${which}, which has no rules for a tool. An address finds the most recently played run that is open to watchers; if that is not the one you are playing, open that one to watchers and connect again.`,
331	        }),
332	      );
333	    } else if (!fits(profile, app || undefined)) {
334	      lines.push(
335	        JSON.stringify({
336	          t: "note",
337	          text: `${which} is set up for ${profile.tool}, so nothing here will reach ${app || "a tool that did not say what it is"}.`,
338	        }),
339	      );
340	    } else {
341	      terms = setupFor(profile, given.includes(whose));
342	      loadout = loadoutFor(profile, gotLoadout.includes(whose));
343	      if (terms) lines.push(terms.frame);
344	      if (loadout) lines.push(loadout.frame);
345	    }
346	    for (const line of lines) {
347	      if ((await poster.post(connectionId, line)) === "gone") {
348	        await deps.live.disconnect(connectionId);
349	        return { statusCode: 200 };
350	      }
351	    }
352	    // Remembered only once it has actually gone out. A post that failed
353	    // is a tool that never got its terms, and marking it given would
354	    // leave the next attach short of them for the rest of the run.
355	    const patch: { termsGiven?: string[]; loadoutGiven?: string[] } = {};
356	    if (terms?.gave && !given.includes(whose)) patch.termsGiven = [...given, whose];
357	    if (loadout?.gave && !gotLoadout.includes(whose)) patch.loadoutGiven = [...gotLoadout, whose];
358	    if (patch.termsGiven || patch.loadoutGiven) await deps.store.updateSession(conn.run, now(), patch);
359	    return { statusCode: 200 };
360	  }
361	
362	  /**
363	   * A tool saying what happened in the game.
364	   *
365	   * The one thing that travels the other way. It is a mention rather than
366	   * a command: it becomes an ask, exactly as a viewer pressing a button
367	   * does, and the table still decides. Which is why this needs the host
368	   * to have switched asks on, and is refused as politely as anything else
369	   * when they have not.
370	   */
371	  if (conn.control && m["t"] === "event" && conn.run) {
372	    /**
373	     * Something the game said. Dropped for several good reasons, and it
374	     * used to be dropped in silence: every one of these answered 200, the
375	     * tool logged that it had said so, and a death counted nowhere. The
376	     * tool is told now, because "it went nowhere and here is why" is the
377	     * one thing it cannot work out from its end.
378	     */
379	    const drop = async (why: string): Promise<WsResult> => {
380	      const poster = deps.poster;
381	      if (poster) {
382	        try {
383	          await poster.post(connectionId, JSON.stringify({ t: "note", text: why }));
384	        } catch (error) {
385	          console.error("live: could not say why an event went nowhere", error);
386	        }
387	      }
388	      return { statusCode: 200 };
389	    };
390	    const meant = askFor(String(m["kind"] ?? ""));
391	    if (!meant) return drop(`This run has nothing it calls "${String(m["kind"] ?? "")}", so nothing was counted.`);
392	    const session = await deps.store.getSession(conn.run);
393	    if (!session || session.meta.deletedAt || session.meta.endedAt) return drop("That run has ended, so nothing was counted.");
394	    // Taking asks stays the host's word, per run, the same as it is for
395	    // chat. A tool cannot switch it on by being attached.
396	    if (!session.meta.askPolicy)
397	      return drop(
398	        "This run is not taking asks, so nothing was counted. Switch it on under Settings, Stream, Chat, and the game's word counts from then on.",
399	      );
400	    const who = conn.seat || "the game";
401	    const at = now();
402	    if (!askAllowed(conn.run, who, Date.parse(at)).ok) return drop("Too many, too quickly: this one was not counted.");
403	    const ask: Ask = { id: randomBytes(6).toString("hex"), kind: "move", move: meant.move, name: who, via: "the game", at };
404	    await deps.store.addAsk(conn.run, ask);
405	    const poster = deps.poster;
406	    // And when it did land, which of the two landings it was: taken, or
407	    // put in front of somebody. A tool that cannot tell those apart from
408	    // having been ignored is a tool nobody believes.
409	    if (poster) {
410	      const heard =
411	        session.meta.askPolicy === "auto" ? "Counted." : "Said. It is in the run's asks, waiting for whoever is at the table to take it.";
412	      try {
413	        await poster.post(connectionId, JSON.stringify({ t: "note", text: heard }));
414	      } catch (error) {
415	        console.error("live: could not say an event landed", error);
416	      }
417	    }
418	    if (poster) {
419	      const line = JSON.stringify({
420	        t: "gesture",
421	        id: conn.run,
422	        kind: "ask",
423	        data: { ask: ask.id, kind: ask.kind, move: ask.move, name: who, via: ask.via, policy: session.meta.askPolicy },
424	        at,
425	      });
426	      for (const w of await deps.live.watchers(conn.run)) {
427	        if (w.control) continue;
428	        try {
429	          if ((await poster.post(w.connectionId, line)) === "gone") await deps.live.disconnect(w.connectionId);
430	        } catch (error) {
431	          console.error("live: could not pass an ask on", error);
432	        }
433	      }
434	    }
435	
436	    return { statusCode: 200 };
437	  }
438	
439	  // A link's socket, and a scene's, watch the one run they were opened for
440	  // and take no requests.
441	  if (conn.sub.startsWith("public:") || conn.sub.startsWith("stream:")) return { statusCode: 200 };
442	  // A gesture: something happening at the table that is not a move, dice
443	  // in the air, a step opened, a card turned, passed straight on to
444	  // everyone watching the run and kept nowhere. Only a member sends one,
445	  // it is small, and its kind is a short word the app gives meaning to.
446	  if (m["t"] === "gesture" && typeof m["id"] === "string" && typeof m["kind"] === "string") {
447	    const id = m["id"];
448	    const kind = m["kind"];
449	    if (id.length > 200 || !/^[a-z][a-z0-9-]{0,31}$/.test(kind)) return { statusCode: 400, body: "a gesture has an id and a kind" };
450	    const data = m["data"] !== undefined && typeof m["data"] === "object" && m["data"] !== null ? m["data"] : {};
451	    if (JSON.stringify(data).length > 2000) return { statusCode: 400, body: "a gesture is small" };
452	    const session = await deps.store.getSession(id);
453	    const member = session && !session.meta.deletedAt ? session.members.find((x) => x.sub === conn.sub) : undefined;
454	    if (!member) return { statusCode: 200 };
455	    const line = JSON.stringify({ t: "gesture", id, kind, data, ...(member.name ? { from: member.name } : {}), at: now() });
456	    const poster = deps.poster;
457	
458	    /**
459	     * The loadout, handed out again on purpose.
460	     *
461	     * Every other gesture is passed on. This one means something to the
462	     * server, because the thing standing in the way of handing a loadout
463	     * out twice is a record the server keeps.
464	     *
465	     * `loadoutGiven` exists so that a tool which dropped and reconnected
466	     * is not given the runes again, and it has to go on doing that. But
467	     * a run whose host has picked a different loadout and pressed the
468	     * button is not a reconnect; it is somebody deciding that this table
469	     * is playing with different gear from now on. So the record is
470	     * cleared here and rebuilt from what actually goes out, and a
471	     * reconnect a second later is short of the gifts exactly as before.
472	     *
473	     * The loadout only. The pack's terms are a separate effect and are
474	     * not re-sent: the button is under a list of loadouts and says it
475	     * hands out the loadout, and sending the terms with it handed over
476	     * the pack's own gifts a second time as well.
477	     *
478	     * The owner only. Every member can send a gesture, and that is right
479	     * for dice in the air and a step opening; handing somebody a hundred
480	     * and twenty thousand runes is not something one player at the table
481	     * should be able to do to the others.
482	     *
483	     * Asked of the run rather than of the member row. Both say the same
484	     * thing today, and the run is the one that says it first: a member
485	     * row carries whatever was written into it when somebody joined.
486	     */
487	    if (kind === "setup") {
488	      if (session?.meta.ownerSub !== conn.sub) return { statusCode: 200 };
489	      if (!poster) return { statusCode: 200 };
490	      const watchers = await deps.live.watchers(id);
491	      const attached = watchers.filter((w) => w.control);
492	      const profile = attached.length > 0 ? profileOf((await deps.store.getSnapshot(id))?.snapshot) : null;
493	      const gave: string[] = [];
494	      await Promise.all(
495	        watchers.map(async (w) => {
496	          // The table is told in words that it happened; a tool is told
497	          // in operations, which is the same split as everywhere else.
498	          let out = w.connectionId === connectionId ? null : line;
499	          if (w.control) {
500	            if (!profile || !fits(profile, w.app)) return;
501	            // `false`, because being handed one is the whole point: the
502	            // record that would hold the gifts back has just been dropped.
503	            const loadout = loadoutFor(profile, false);
504	            if (!loadout) return;
505	            out = loadout.frame;
506	            if (loadout.gave) gave.push(w.seat || "the table");
507	          }
508	          if (!out) return;
509	          try {
510	            if ((await poster.post(w.connectionId, out)) === "gone") await deps.live.disconnect(w.connectionId);
511	          } catch (error) {
512	            console.error("live: could not hand out the setup", error);
513	          }
514	        }),
515	      );
516	      // Written after the fact, from what went out rather than from what
517	      // was meant to: a tool that was not reachable did not get its
518	      // loadout, and saying it did would leave it short on the next
519	      // attach. `termsGiven` is left alone, because the terms did not
520	      // move.
521	      await deps.store.updateSession(id, now(), { loadoutGiven: [...new Set(gave)] });
522	      return { statusCode: 200 };
523	    }
524	
525	    if (poster) {
526	      const watchers = (await deps.live.watchers(id)).filter((w) => w.connectionId !== connectionId);
527	      // A tool attached to somebody's game is told in operations rather
528	      // than in words, and the profile that decides which is read only
529	      // when one of them is listening.
530	      const attached = watchers.filter((w) => w.control);
531	      const profile = attached.length > 0 ? profileOf((await deps.store.getSnapshot(id))?.snapshot) : null;
532	      await Promise.all(
533	        watchers.map(async (w) => {
534	          const lines = !w.control ? [line] : profile && fits(profile, w.app) ? framesForGesture(profile, kind, data, w.seat) : [];
535	          for (const out of lines) {
536	            try {
537	              if ((await poster.post(w.connectionId, out)) === "gone") {
538	                await deps.live.disconnect(w.connectionId);
539	                return;
540	              }
541	            } catch (error) {
542	              console.error("live: could not pass a gesture on", error);
543	            }
544	          }
545	        }),
546	      );
547	    }
548	    return { statusCode: 200 };
549	  }
550	  if (m["t"] === "watch" && typeof m["id"] === "string" && m["id"].length > 0 && m["id"].length <= 200) {
551	    // A session or a race that is not theirs to see looks exactly like one
552	    // that is not there: the socket confirms nothing.
553	    const session = await deps.store.getSession(m["id"]);
554	    const inSession = Boolean(session && !session.meta.deletedAt && session.members.some((x) => x.sub === conn.sub));
555	    const race = inSession ? null : await deps.races.getRace(m["id"]);
556	    const inRace = Boolean(race && race.entries.some((e) => e.sub === conn.sub));
557	    if (!inSession && !inRace) return { statusCode: 200 };
558	    await deps.live.watch(connectionId, m["id"], conn.sub, now());
559	    if (conn.deck) {
560	      // A deck is told a run is on it the same way a page is told a tool
561	      // is: the row says so, and the table hears it.
562	      await deps.live.connect(connectionId, conn.sub, now(), { deck: true, run: m["id"] });
563	      await tellWhoIsAttached(m["id"]);
564	    }
565	    // A run just came under a device. A deck that has been sitting on "No
566	    // run open" all evening is the one thing waiting to hear it.
567	    await tellDecks(conn.sub);
568	    return { statusCode: 200 };
569	  }
570	  return { statusCode: 400, body: "unknown message" };
571	}
572	
573	/* ---- the Lambda ---------------------------------------------------------- */
574	
575	let deps: WsDeps | undefined;
576	
577	export async function handler(event: WsEvent): Promise<WsResult> {
578	  if (!deps) {
579	    const clientId = process.env["WORKOS_CLIENT_ID"] ?? "";
580	    const cliClientId = process.env["WORKOS_CLI_CLIENT_ID"] ?? "";
581	    const table = process.env["TABLE_NAME"] ?? "";
582	    deps = {
583	      live: dynamoLive({ table }),
584	      store: dynamoStore({ table, bucket: process.env["BUCKET_NAME"] ?? "" }),
585	      races: dynamoRaces({ table }),
586	      verify: (authorization) => verifyToken(authorization, [clientId, cliClientId]),
587	      ...(process.env["WS_ENDPOINT"] ? { poster: apiGatewayPoster(process.env["WS_ENDPOINT"]) } : {}),
588	    };
589	  }
590	  try {
591	    return await route(event, deps);
592	  } catch (error) {
593	    console.error(error);
594	    return { statusCode: 500, body: "something went wrong on this side" };
595	  }
596	}
